div.script:
(function () {
    // Remove duplicate placeholders (keep first)
    document.querySelectorAll('div#irg-academic-upload').forEach(function (el, idx) {
        if (idx > 0) { el.parentNode.removeChild(el); }
    });

    var wrapper = document.getElementById('irg-academic-upload');
    if (!wrapper) { return; }
    var dropzone = wrapper.querySelector('.irg-dropzone');
    var fileInput = wrapper.querySelector('input.irg-file-input');
    var fileList = wrapper.querySelector('.irg-file-list');

    function renderFileList(files) {
        fileList.innerHTML = '';
        if (!files || files.length === 0) { return; }
        for (var i = 0; i < files.length; i++) {
            var f = files[i];
            var item = document.createElement('div');
            item.textContent = f.name + ' (' + Math.round(f.size/1024) + ' KB)';
            fileList.appendChild(item);
        }
    }

    // Click on dropzone opens file selector
    dropzone.addEventListener('click', function () { fileInput.click(); });

    // File input change
    fileInput.addEventListener('change', function (ev) { renderFileList(this.files); });

    // DnD handlers
    ['dragenter','dragover'].forEach(function (evt) {
        dropzone.addEventListener(evt, function (e) { e.preventDefault(); e.stopPropagation(); dropzone.style.borderColor = '#0d6efd'; dropzone.style.background = '#fff'; });
    });
    ['dragleave','drop'].forEach(function (evt) {
        dropzone.addEventListener(evt, function (e) { e.preventDefault(); e.stopPropagation(); dropzone.style.borderColor = '#cfeefc'; dropzone.style.background = ''; });
    });
    dropzone.addEventListener('drop', function (e) {
        var dt = e.dataTransfer;
        if (!dt || !dt.files || dt.files.length === 0) { return; }
        // Replace file input files (DataTransfer available in modern browsers)
        try {
            fileInput.files = dt.files;
        } catch (err) {
            // Fallback: nothing to do — some browsers block programmatic assignment
        }
        renderFileList(dt.files);
    });

    // Show modal if academic_upload param present
    var academicParam = "";
    academicParam = "" + ( (request.params.get('academic_upload') and request.params.get('academic_upload')) or '' );
    if (academicParam) {
        var message = '';
        if (academicParam === 'ok') { message = 'Documentación subida correctamente.'; }
        else if (academicParam === 'empty') { message = 'No se recibió ningún archivo.'; }
        else if (academicParam === 'forbidden') { message = 'No se pudo validar el pedido para adjuntar archivos.'; }
        else if (academicParam === 'missing_order') { message = 'Pedido no encontrado.'; }
        if (message) {
            var msgEl = document.getElementById('irgAcademicUploadMessage');
            if (msgEl) { msgEl.textContent = message; }
            if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
                var modalEl = document.getElementById('irgAcademicUploadModal');
                var modal = new bootstrap.Modal(modalEl);
                modal.show();
            } else {
                alert(message);
            }
        }
    }
})();
